"""Hand-read Veinot1997 source content. Source facts and interpretations separated."""
SID='veinot1997'
KEYS=['qdoh']+[f'ester-2{x}' for x in 'abcde']+['pyrenecarbonyl-chloride']+[f'acylimidazole-3{x}' for x in 'abcde']+['reagent-conditioning','nmr','ftir','uv-visible','tem','unfunctionalized-control','direct-acylchloride-degradation','prolonged-degradation','characterization']
R={k:'veinot-1997-'+k for k in KEYS}
SECTIONS=[{'id':k,'title':t,'items':[]} for k,t in [('precursors','Precursors'),('protocol','Synthesis protocol'),('structures','Final structures'),('properties','Properties'),('intuition','Chemical intuition'),('sources','Sources and limitations')]]
def ev(p,where):return {'source_id':SID,'document_role':'main','pdf_page':p,'printed_page':2116+p,'locator':f'Main PDF p. {p}, printed p. {2116+p}, {where}'}
def item(sec,key,title,text,p,where,records=(),compounds=(),kind='reported_source_fact',notes=(),extra=(),facts=()):
 e=[ev(p,where)]+[ev(q,w) for q,w in extra]
 d={'id':key,'title':title,'text':text,'claim_type':kind,'sample_scope':{'compound_labels':list(compounds),'physical_batch_id':None,'state':title,'link_limit':'Source compound class and characterization context only. Shared labels do not establish identical aliquots, specimens or independent physical batches.'},'evidence':e,'source_locators':[x['locator'] for x in e],'canonical_links':[{'record_id':R[k],'json_pointer':'','relation':'Source-context association; compound identity and specimen limitations remain explicit.'} for k in records],'notes':list(notes),'facts':list(facts),'training_eligible':False}
 next(s for s in SECTIONS if s['id']==sec)['items'].append(d);return d

